		tgt.[address2_telephone3] = stg.[address2_telephone3],
		tgt.[address2_upszone] = stg.[address2_upszone],
		tgt.[address2_utcoffset] = stg.[address2_utcoffset],
		tgt.[businessunitid] = stg.[businessunitid],
		tgt.[calendarid] = stg.[calendarid],
